import base64, zlib, os
F = {}
F['src/tests/v2/BlueprintContract.test.ts'] = ''
F['src/tests/components/passwordProblem.test.ts'] = ''
F['e2e/v2/screens.spec.ts'] = ''
F['e2e/v2/platform.spec.ts'] = ''
F['playwright.config.ts'] = ''
for p, d in F.items():
    os.makedirs(os.path.dirname(p) or '.', exist_ok=True)
    open(p, 'wb').write(zlib.decompress(base64.b64decode(d)))
    print('wrote', p)
print('Done.')
